import {CheckIcon, ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import {Button, Details, Stack, Text, useDetails} from '@primer/react'
import {useEffect, useRef} from 'react'

import styles from './Step.module.css'

type StepProps = {
  index: number
  title: string
  isActive: boolean
  isComplete?: boolean
  children: React.ReactNode
}

export const Step = ({index, title, isActive, isComplete, children}: StepProps) => {
  const {getDetailsProps, setOpen} = useDetails({defaultOpen: isActive})
  const detailsProps = getDetailsProps()

  if (isComplete) detailsProps.open = false

  const leadingVisual = isComplete ? (
    <CheckIcon aria-label="Done" className="fgColor-success" data-testid={`stepper-step-${index}-checked`} />
  ) : detailsProps.open ? (
    <ChevronDownIcon data-testid={`stepper-step-${index}-unchecked`} />
  ) : (
    <ChevronRightIcon data-testid={`stepper-step-${index}-unchecked`} />
  )

  const prevIsActiveRef = useRef(isActive)
  useEffect(() => {
    if (prevIsActiveRef.current !== isActive) {
      prevIsActiveRef.current = isActive
      setOpen(isActive)
    }
  }, [isActive, setOpen])

  return (
    <Details className={`rounded-2 ${styles.Step}`} {...detailsProps} inert={isComplete}>
      <Button
        block
        as="summary"
        size="large"
        className="tmp-px-2"
        variant="invisible"
        alignContent="start"
        leadingVisual={leadingVisual}
        data-testid={`stepper-button-${index}`}
      >
        <Text weight="semibold">{title}</Text>
      </Button>

      <Stack
        gap="normal"
        align="start"
        className="fgColor-muted tmp-pl-5 tmp-pb-3"
        data-testid={`stepper-panel-${index}`}
      >
        {children}
      </Stack>
    </Details>
  )
}
