import {verifiedFetch} from '@github-ui/verified-fetch'

export const handleSubmitFormAction = async (formAction: string) => {
  try {
    const result = await verifiedFetch(formAction, {
      method: 'POST',
    })

    if (result.redirected) {
      // The rails endpoint returns a 302 redirect but does not update the React partial.
      // We need to do this update manually to get the user to the correct page returned by Rails.
      window.location.href = result.url
    } else {
      throw new Error('did not receive redirect from form action submission')
    }
  } catch {
    // TODO: log error to monitoring service
  }
}
